        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd311v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd311v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd311v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd311v)row);
        public void Dispose() => writer.Dispose();
    }
}